import itertools, random

def sorted_seq(a):
    return all(a[i] <= a[j] for i in range(len(a)) for j in range(i, len(a)))

def valid_permut(a,b):
    from collections import Counter
    return Counter(a)==Counter(b)

def check_invariants(a, verbose=False):
    orig=a[:]
    n=len(a)
    for i in range(n):
        # before inner loop
        assert valid_permut(a,orig), ('outer perm', i, a)
        assert sorted_seq(a[:i]), ('outer sorted', i, a)
        for j in range(n):
            # check inner invariants at entry
            inv2 = (j < i) <= False or all(a[k] <= a[i] for k in range(j))
            inv3 = (j < i-1) <= False or sorted_seq(a[:i])
            inv4 = (j >= i) <= False or sorted_seq(a[:i+1])
            if not inv2:
                print('invariant2 fails at entry', i,j,a,'inv2')
                return i,j,2
            if not inv3:
                print('invariant3 fails at entry', i,j,a,'inv3')
                return i,j,3
            if not inv4:
                print('invariant4 fails at entry', i,j,a,'inv4')
                return i,j,4
            # body
            if a[i] < a[j]:
                a[i], a[j] = a[j], a[i]
            # after body, for loop will increment and then check, so need invariants at state after body? Actually Dafny checks inv after body and after increment? Let's simulate after body:
            if not inv2:
                # inv2 after body before increment? We can check after increment at next loop, but Dafny checks at top after increment.
                pass
        assert sorted_seq(a), (i,a)
    return None

# enumerate some arrays
for n in range(0,6):
    for a in itertools.permutations(range(n)):
        a=list(a)
        if n>=5 and random.random()<0.99: continue
        res=check_invariants(a, verbose=False)
        if res:
            print('FAIL', n, a, res)
            # don't stop maybe
            break
    else:
        continue
    break
